export function OfflineState({
  title = "{{title}}",
  message = "{{message}}",
  lastSynced = "{{lastSynced}}",
  retrying = {{retrying}},
}) {
  return (
    <div role="alert" style={{ display: "flex", alignItems: "flex-start", gap: 12, maxWidth: 380, padding: "14px 16px",
      boxSizing: "border-box", borderRadius: 10, background: "color-mix(in srgb, #8C1F17 8%, #FAF7F2)",
      border: "1px solid #8C1F17", font: "13.5px/1.45 system-ui, sans-serif", color: "#241430" }}>
      <span aria-hidden="true" style={{ width: 22, height: 22, borderRadius: "50%", flexShrink: 0, background: "#8C1F17",
        marginTop: 1, display: "grid", placeItems: "center", fontSize: 11, color: "#FAF7F2",
        animation: retrying ? "offline-react-spin 1.1s linear infinite" : "none" }}>⚡</span>
      <div>
        <p style={{ margin: "0 0 2px", fontWeight: 700 }}>{title}</p>
        <p style={{ margin: 0, color: "#241430b3" }}>{message}</p>
        <p style={{ margin: "6px 0 0", fontSize: 11.5, color: "#8C1F17", fontWeight: 600 }}>Last synced {lastSynced}{retrying ? " · reconnecting…" : ""}</p>
      </div>
      <style>{`@keyframes offline-react-spin { to { transform: rotate(360deg); } }`}</style>
    </div>
  );
}
